/**
 * Type-level views of `operations` (generated by openapi-typescript), keyed
 * by operationId: `QueryOf<"listings.list">`, `ResponseOf<"sales.ship">`, ...
 */
import type { operations } from "../generated/openapi.js";

export type OperationId = keyof operations;

type Op<K extends OperationId> = operations[K];
type IsNever<T> = [T] extends [never] ? true : false;

/** Query parameters of an operation (`never` when it takes none). */
export type QueryOf<K extends OperationId> = Op<K>["parameters"] extends { query?: infer Q } ? NonNullable<Q> : never;

/** Path parameters of an operation. */
export type PathOf<K extends OperationId> = Op<K>["parameters"] extends { path?: infer P } ? NonNullable<P> : never;

type RequestBody<K extends OperationId> = Op<K> extends { requestBody?: infer B } ? NonNullable<B> : never;

/** JSON request body of an operation (`never` when it takes none). */
export type BodyOf<K extends OperationId> =
    IsNever<RequestBody<K>> extends true ? never
        : RequestBody<K> extends { content: { "application/json": infer J } } ? J : never;

type Responses<K extends OperationId> = Op<K>["responses"];
type SuccessCode<R> = Extract<keyof R, 200 | 201 | 202 | 204 | "200" | "201" | "202" | "204">;
type JsonOf<R> = R extends { content: { "application/json": infer J } } ? J : undefined;

/** Parsed JSON body of the operation's success response. */
export type ResponseOf<K extends OperationId> = JsonOf<Responses<K>[SuccessCode<Responses<K>>]>;

/** Element type of a list operation's `data` array. */
export type ItemOf<K extends OperationId> = ResponseOf<K> extends { data: (infer I)[] } ? I : never;

/** Shape every cursor-paginated response shares. */
export interface PageShape<Item> {
    object: "list";
    data: Item[];
    has_more: boolean;
    next_cursor: string | null;
}

/** JSON values a request can carry. */
export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue | undefined };

/** Query values the SDK can serialise. */
export type QueryValue = string | number | boolean | Date | null | undefined | readonly (string | number | boolean)[];
